"""Bounded, saved batches of actual stored cardiac cells and occupied volumes."""
from pathlib import Path
import argparse,json,sys,time
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from geometry_tools.model import AtlasReader
from geometry_tools.common import atomic_json,digest_file
from geometry_tools.tissue import validate_cells
ap=argparse.ArgumentParser();ap.add_argument('--bank',required=True);ap.add_argument('--range',nargs=2,type=int);ap.add_argument('--parts',nargs='+');ap.add_argument('--report-name');ap.add_argument('--checkpoints');ap.add_argument('--max-pairs',type=int,default=1500000);ap.add_argument('--max-tests',type=int,default=16000000);args=ap.parse_args();h=ROOT/'.local-models/geometry-workbench/heart';bank=h/args.bank;meta=json.loads((bank/'emission.json').read_text());assert meta['passed_storage']and digest_file(bank/'cells.bin')==meta['bank_sha256'];reader=AtlasReader();mini=dict(chunks=[dict(url='/local-models/'+str((bank/'cells.bin').relative_to(ROOT/'.local-models')))]);names=list(meta['parts']);selected=args.parts if args.parts else names[slice(*args.range)]if args.range else names;assert len(set(selected))==len(selected)and set(selected)<=set(names);start=time.monotonic();meshes={pid:reader.read_part(mini,dict(meta['parts'][pid],chunk=0,geometryOrigin=[0.,0.,0.]),frame='heart-native-local-metres')for pid in selected};result=validate_cells(meshes,max_pairs=args.max_pairs,max_tests=args.max_tests,checkpoint_directory=h/args.checkpoints if args.checkpoints else bank/'checkpoints');result.update(bank_sha256=meta['bank_sha256'],elapsed_seconds=time.monotonic()-start,part_ids=selected,complete_bank=args.range is None and args.parts is None);name=args.report_name or ('checked-geometry.json'if result['complete_bank']else f'checks-{args.range[0]}-{args.range[1]}.json'if args.range else 'checks-selected.json');atomic_json(bank/name,result);print(json.dumps({k:result[k]for k in ['passed','failures','complete_bank','elapsed_seconds']}),flush=True)
